package com.opensocket.aievent.core.a2a.application.service;
import java.time.*;import com.opensocket.aievent.core.a2a.*;import com.opensocket.aievent.core.a2a.application.port.out.A2ADispatchRepairPort;import com.opensocket.aievent.core.integration.handoff.HandoffContextService;
/** Lease-safe executor that delegates repair to the canonical authority for each resource. */
public final class A2ACanonicalRepairExecutor {private final A2AReconciliationCaseRepository cases;private final A2AUnifiedReconciliationService unified;private final A2AResultCompletionCoordinator results;private final HandoffContextService handoffs;private final A2ACancellationService cancellations;private final A2ADispatchRepairPort dispatch;
 public A2ACanonicalRepairExecutor(A2AReconciliationCaseRepository c,A2AUnifiedReconciliationService u,A2AResultCompletionCoordinator r,HandoffContextService h,A2ACancellationService x,A2ADispatchRepairPort d){cases=c;unified=u;results=r;handoffs=h;cancellations=x;dispatch=d;}
 public int executeDue(String worker,int limit){int count=0;OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);for(A2AReconciliationCase c:cases.claimExecutable(worker,now,now.plusSeconds(90),limit)){boolean ok=false,retry=true;String ev="repair:"+c.getCaseId()+":"+c.getRepairAttemptNo(),code="REPAIR_UNSUPPORTED",reason="No safe canonical repair is available";try{A2ARepairAction action=A2ARepairAction.valueOf(c.getRepairAction());switch(action){case RECONCILE_RESULT,RECOMPUTE_PARENT_AGGREGATION->{results.process(c.getTenantId(),required(c.getResultId(),"resultId"),worker);ok=true;code="RESULT_REPAIRED";reason="A2A Result Authority completed deterministic processing";}case RETRY_HANDOFF_RELEASE->{handoffs.retryRelease(c.getTenantId(),required(c.getHandoffSnapshotId(),"handoffSnapshotId"),"SYSTEM",worker,"Unified reconciliation repair");ok=true;code="HANDOFF_REPAIRED";reason="Handoff Authority retried release";}case RECONCILE_CANCELLATION->{cancellations.reconcile(c.getTenantId(),required(c.getCancellationId(),"cancellationId"),worker,"Unified reconciliation repair",ev);ok=true;code="CANCELLATION_REPAIRED";reason="Cancellation Authority reconciled runtime evidence";}case RECONCILE_DISPATCH->{var out=dispatch.reconcile(required(c.getDispatchRequestId(),"dispatchRequestId"));ok=out.repaired();retry=out.retryable();ev=out.evidenceReference();code=out.reasonCode();reason=out.reason();}default->{retry=false;code="MANUAL_AUTHORITY_REQUIRED";}}}catch(Exception ex){code=errorCode(ex);reason=ex.getMessage();}unified.recordOutcome(new A2ARepairOutcomeCommand(c.getTenantId(),c.getCaseId(),c.getVersion(),ok,retry,ev,code,reason,worker));count++;}return count;}
 private static String required(String v,String n){if(v==null||v.isBlank())throw new IllegalStateException(n+" is required");return v;}private static String errorCode(Exception e){String v=e.getMessage();return v==null?e.getClass().getSimpleName().toUpperCase():v.split(":",2)[0].replace(' ','_').toUpperCase();}}
